    private List<Category> _categories = new();
    private Category _edit = new();
    private bool _showModal;
    private string? _alert, _formError;

    protected override async Task OnInitializedAsync() => await LoadAsync();

    private async Task LoadAsync()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        _categories = await db.Categories.Include(c => c.Products).OrderBy(c => c.DisplayOrder).ToListAsync();
    }

    private void OpenAdd()
    {
        _edit = new Category { DisplayOrder = _categories.Count + 1, IsActive = true };
        _formError = null;
        _showModal = true;
    }

    private void OpenEdit(Category c)
    {
        _edit = new Category { Id = c.Id, Name = c.Name, Description = c.Description, DisplayOrder = c.DisplayOrder, IsActive = c.IsActive };
        _formError = null;
        _showModal = true;
    }

    private async Task SaveAsync()
    {
        if (string.IsNullOrWhiteSpace(_edit.Name))
        {
            _formError = "Tên dòng máy không được để trống!";
            return;
        }

        await using var db = await DbFactory.CreateDbContextAsync();
        if (_edit.Id == 0)
        {
            db.Categories.Add(new Category { Name = _edit.Name.Trim(), Description = _edit.Description, DisplayOrder = _edit.DisplayOrder, IsActive = _edit.IsActive });
            _alert = $"Đã thêm dòng máy: {_edit.Name}";
        }
        else
        {
            var existing = await db.Categories.FindAsync(_edit.Id);
            if (existing != null)
            {
                existing.Name = _edit.Name.Trim();
                existing.Description = _edit.Description;
                existing.DisplayOrder = _edit.DisplayOrder;
                existing.IsActive = _edit.IsActive;
                _alert = $"Cập nhật dòng máy: {existing.Name}";
            }
        }
        await db.SaveChangesAsync();
        _showModal = false;
        await LoadAsync();
    }

    private async Task DeleteAsync(Category c)
    {
        if (!await JS.InvokeAsync<bool>("confirm", "Bạn có chắc muốn xóa dòng máy này? Toàn bộ máy thuộc dòng này cũng sẽ bị xóa!")) return;

        await using var db = await DbFactory.CreateDbContextAsync();
        var category = await db.Categories.FindAsync(c.Id);
        if (category == null) return;
        try
        {
            db.Categories.Remove(category);
            await db.SaveChangesAsync();
            _alert = $"Đã xóa dòng máy: {category.Name}";
        }
        catch (DbUpdateException)
        {
            _alert = $"Không thể xóa '{category.Name}' vì có sản phẩm đã phát sinh đơn hàng.";
        }
        await LoadAsync();
    }

